   ============================================================ */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 1rem;
  background: var(--color-primary);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: 0 0 var(--radius-input) var(--radius-input);
  font-weight: 600;
  z-index: 9999;
  text-decoration: none;
}

