  background: var(--color-header-bg);
  border-bottom: 1px solid var(--color-border);
  padding-block: 1rem;
}

.logo {
  font-weight: 700;
  font-size: 1.125rem;
  color: var(--color-primary);
  letter-spacing: -0.01em;
}

