 * ContactForm — client-side validation and submission handler.
 *
 * Accessibility contract:
 * - Validation runs only on submit (not on initial render).
 * - On failure, focus moves to the first invalid field.
 * - Each error message is linked to its field via aria-describedby
 *   and aria-invalid, so screen readers announce the error when
 *   the field receives focus.
 * - A live region (#form-status) announces the overall result.
 */

(function () {
  "use strict";

  const form = document.getElementById("contact-form");
  const statusEl = document.getElementById("form-status");

  // ── Field definitions ──────────────────────────────────────────────────────
  const fields = [
    {
      id: "full-name",
      errorId: "full-name-error",
      validate(value) {
        if (!value.trim()) return "Enter your full name.";
        return null;
      },
    },
    {
      id: "email",
      errorId: "email-error",
      validate(value) {
        if (!value.trim()) return "Enter your email address.";
        // Basic RFC-5322-ish check adequate for client-side UX.
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
          return "Enter a valid email address, like name@example.com.";
        }
        return null;
      },
    },
  ];

  // ── Helpers ────────────────────────────────────────────────────────────────
  function setFieldError(field, message) {
    const input = document.getElementById(field.id);
    const errorEl = document.getElementById(field.errorId);

    input.setAttribute("aria-invalid", "true");
    errorEl.textContent = message;
    errorEl.removeAttribute("hidden");
  }

  function clearFieldError(field) {
    const input = document.getElementById(field.id);
    const errorEl = document.getElementById(field.errorId);

    input.removeAttribute("aria-invalid");
    errorEl.textContent = "";
    errorEl.setAttribute("hidden", "");
  }

  function clearAllErrors() {
    fields.forEach(clearFieldError);
    statusEl.textContent = "";
    statusEl.className = "form-status";
  }

  function showStatus(message, type) {
    statusEl.textContent = message;
    statusEl.className = `form-status form-status--${type}`;
  }

  // ── Submit handler ─────────────────────────────────────────────────────────
  form.addEventListener("submit", function (event) {
    event.preventDefault();
    clearAllErrors();

    let firstInvalidField = null;

    fields.forEach(function (field) {
      const input = document.getElementById(field.id);
      const error = field.validate(input.value);
      if (error) {
        setFieldError(field, error);
        if (!firstInvalidField) firstInvalidField = input;
      }
    });

    if (firstInvalidField) {
      // Move focus to the first invalid control so screen readers
      // announce its associated error message.
      firstInvalidField.focus();
      showStatus(
        "Please fix the errors below before sending your message.",
        "error"
      );
      return;
    }

    // ── Simulate successful submission ────────────────────────────────────
    showStatus(
      "Your message has been sent. We'll get back to you within one business day.",
      "success"
    );
    form.reset();
  });

  // ── Clear per-field error as the user corrects their input ─────────────────
  fields.forEach(function (field) {
    const input = document.getElementById(field.id);
    input.addEventListener("input", function () {
      if (input.getAttribute("aria-invalid") === "true") {
        const error = field.validate(input.value);
        if (!error) clearFieldError(field);
      }
    });
  });
